MATCH (target:PlantItem {tag: 'V-37301'})-[:line_to]-(v:Valve)<-[:control]-(actuator:PlantItem)<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'H-25501'}), (b:PlantItem {tag: 'EA-25501'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x.tag <> 'R-25501' AND y.tag <> 'R-25501')+ (b)
       } AS reachable_without_R

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'K-9601'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'D-54801'}), (b:PlantItem {tag: 'P-54801'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'E-33101'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
