    MATCH (w:PlantItem:Valve)
    WHERE w <> v
      AND EXISTS { (p)-[:line_to*1..]->(w) }
      AND EXISTS { (w)-[:line_to*1..]->(v) }
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

